268: // ---------------------------------------------------------------- UI: HUD
269: let hudTick = 0;
270: function updateHUD(dt) {
271:   els.scoreBlue.textContent = game.scores.blue;
272:   els.scoreOrange.textContent = game.scores.orange;
273:   els.pauseBlue.textContent = game.scores.blue;
274:   els.pauseOrange.textContent = game.scores.orange;
275: 
276:   if (game.overtime) {
277:     const total = Math.floor(game.otClock);
278:     els.clock.textContent = `+${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
279:     els.matchState.textContent = 'OVERTIME';
280:     $('.clock-wrap').classList.add('overtime');
281:     $('.clock-wrap').classList.remove('hurry');
282:   } else {
283:     const total = Math.max(0, Math.ceil(game.clock));
284:     els.clock.textContent = `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
285:     els.matchState.textContent = 'REGULATION';
286:     $('.clock-wrap').classList.toggle('hurry', game.clock <= 30);
287:     $('.clock-wrap').classList.remove('overtime');
288:   }
289: 
290:   const boostPct = Math.max(0, Math.min(100, (player.boost / player.stats.capacity) * 100));
291:   els.boostValue.textContent = Math.round(player.boost);
292:   els.boostFill.style.width = `${boostPct}%`;
293:   els.boostItem.textContent = player.build.chosen.boost.name.toUpperCase();
294:   els.regenTag.textContent = player.stats.regen > 0 ? `+${player.stats.regen}/S REGEN` : 'NO REGEN';
295: 
296:   const kph = Math.round(player.speed * 3.6);
297:   els.speed.textContent = String(kph).padStart(3, '0');
298:   const maxKph = player.stats.maxSpeed * 1.3 * 3.6;
299:   els.sonicBar.style.setProperty('--speed', `${Math.min(100, (kph / maxKph) * 100)}%`);
300:   els.hudSpeed.classList.toggle('sonic', player.speed > player.stats.maxSpeed * 0.93);
301: 
302:   els.jumpPip.classList.toggle('active', player.grounded || player.jumpCount < 2);
303:   els.dodgePip.classList.toggle('active', !player.grounded && player.jumpCount < 2);
304:   els.driftPip.classList.toggle('active', !!currentInput.drift);
305: 
306:   if (game.toastTimer > 0) {
307:     game.toastTimer -= dt;
308:     if (game.toastTimer <= 0) els.toast.classList.remove('show');
309:   }
310: 
311:   // Only update expensive-ish text ~15fps
312:   hudTick += dt;
313:   if (hudTick > 0.1) {
314:     hudTick = 0;
315:     if (game.mode === 'playing') {
316:       const diff = Math.abs(game.scores.blue - game.scores.orange);
317:       if (game.overtime) els.objective.textContent = 'SUDDEN DEATH — NEXT GOAL WINS';
318:       else if (game.clock <= 30 && diff <= 1) els.objective.textContent = 'CLUTCH TIME — PROTECT THE NET';
319:       else if (diff >= 3) els.objective.textContent = 'MERCY RULE? KEEP THE PRESSURE ON';
320:       else els.objective.textContent = 'FIRST TO THE BALL. LAST TO LEAVE.';
321:     }
322:   }
