425: function togglePause(force) {
426:   if (game.mode === 'menu' || game.mode === 'ended' || game.mode === 'boot') return;
427:   const shouldPause = typeof force === 'boolean' ? force : game.mode !== 'paused';
428:   if (shouldPause) {
429:     if (game.mode === 'paused') return;
430:     game.previousMode = game.mode;
431:     game.mode = 'paused';
432:     els.pause.classList.remove('hidden');
433:     els.pauseBlue.textContent = game.scores.blue;
434:     els.pauseOrange.textContent = game.scores.orange;
435:     audio.setEngine(0, false, false);
436:     audio.ui();
437:   } else {
438:     if (game.mode !== 'paused') return;
439:     game.mode = game.previousMode;
440:     els.pause.classList.add('hidden');
441:     audio.ui();
442:   }
443: }
444: 
445: function closePause() {
446:   els.pause.classList.add('hidden');
447:   if (game.mode === 'paused') game.mode = game.previousMode;
448: }
