450: function beginOvertime() {
451:   game.overtime = true;
452:   game.clock = 0;
453:   game.otClock = 0;
454:   showToast('OVERTIME — NEXT GOAL WINS', 3);
455:   resetKickoff(3.2, false);
456:   showCenter('OVERTIME', 'warn', 1500);
457:   audio.whistle();
458: }
