460: function endMatch() {
461:   game.mode = 'ended';
462:   const won = game.scores.blue > game.scores.orange;
463:   els.endTitle.textContent = won ? 'VICTORY' : 'DEFEAT';
464:   els.endTitle.classList.toggle('loss', !won);
465:   els.endEyebrow.textContent = game.overtime ? 'OVERTIME COMPLETE' : 'MATCH COMPLETE';
466:   els.endBlue.textContent = game.scores.blue;
467:   els.endOrange.textContent = game.scores.orange;
468:   const stats = [
469:     ['GOALS', game.stats.goals],
470:     ['BALL TOUCHES', player.hits],
471:     ['TOP SPEED', `${Math.round(player.topSpeed * 3.6)} KPH`],
472:     ['BOOST BURNED', `${Math.round(player.boostUsed)}`],
473:     ['DISTANCE', `${(game.stats.distance / 1000).toFixed(2)} KM`],
474:     ['POSSESSION', `${Math.round(game.stats.possession)} S`],
475:   ];
476:   els.endStats.innerHTML = stats.map(([label, value]) => (
477:     `<div class="end-stat"><span>${label}</span><b>${value}</b></div>`
478:   )).join('');
479:   els.endFoot.textContent = won
480:     ? 'THE ARENA REMEMBERS YOUR NAME.'
481:     : 'RECALIBRATE THE LOADOUT. RUN IT BACK.';
482:   els.endScreen.classList.remove('hidden');
483:   els.hud.classList.remove('hidden');
484:   audio.setEngine(0, false, false);
485:   if (won) audio.win(); else audio.lose();
486: }
