488: function scoreGoal(team) {
489:   if (game.mode !== 'playing') return;
490:   game.mode = 'goal';
491:   game.stateTime = 0;
492:   game.goalTeam = team;
493:   game.goalSide = team === 'blue' ? 1 : -1;
494:   game.scores[team] += 1;
495:   game.shake = 1.4;
496:   ball.frozen = true;
497:   const scorer = ball.lastTouchCar ? ball.lastTouchCar.name : team.toUpperCase();
498:   const teamData = TEAM[team];
499:   els.goalBanner.classList.toggle('orange', team === 'orange');
500:   els.goalKicker.textContent = `${teamData.name} SCORES`;
501:   els.goalName.textContent = scorer;
502:   els.goalBanner.classList.add('show');
503:   arena.setGoalFlash(team, 1.2);
504:   const pos = new THREE.Vector3(game.goalSide * (FIELD.halfX - 2), 5, Math.max(-8, Math.min(8, ball.pos.z)));
505:   fx.goal(pos, team, teamData.glow);
506:   audio.goal(team);
507:   if (team === 'blue') game.stats.goals += 1;
508:   game.toastTimer = 0;
509:   els.toast.classList.remove('show');
510:   showCenter('', '');
511:   updateHUD(0);
512: }
513: 
514: function afterGoal() {
515:   els.goalBanner.classList.remove('show');
516:   if (game.overtime) { endMatch(); return; }
517:   if (game.clock <= 0) {
518:     if (game.scores.blue === game.scores.orange) beginOvertime();
519:     else endMatch();
