597:   let dy = clientY - cy;
598:   const max = rect.width * 0.34;
599:   const len = Math.hypot(dx, dy);
600:   if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
601:   stick.x = dx / max;
