682: function aiInput(dt) {
683:   const cfg = DIFFICULTIES[game.difficulty];
684:   game.aiTimer -= dt;
685:   game.aiJumpCooldown = Math.max(0, game.aiJumpCooldown - dt);
686:   game.aiBoostCooldown = Math.max(0, game.aiBoostCooldown - dt);
687:   game.aiReverse = Math.max(0, game.aiReverse - dt);
688: 
689:   if (game.aiTimer <= 0) {
690:     game.aiTimer = cfg.reaction + Math.random() * cfg.reaction * 0.6;
691:     const predicted = ball.pos.clone().addScaledVector(ball.vel, 0.12);
692:     const attack = new THREE.Vector3(-FIELD.halfX, 0, 0);
693:     const behind = predicted.clone().sub(attack);
694:     behind.y = 0;
695:     if (behind.lengthSq() < 0.01) behind.set(1, 0, 0);
696:     behind.normalize();
697:     const target = predicted.clone().addScaledVector(behind, 4.4);
698:     const err = cfg.error;
699:     target.x += Math.sin(performance.now() * 0.0013) * err;
700:     target.z += Math.cos(performance.now() * 0.0017) * err * 0.8;
701:     target.x = THREE.MathUtils.clamp(target.x, -FIELD.halfX + 3, FIELD.halfX - 3);
702:     target.z = THREE.MathUtils.clamp(target.z, -FIELD.halfZ + 3, FIELD.halfZ - 3);
703:     target.y = 0;
704: 
705:     // Recover boost if the ball is far away
706:     if (ai.boost < 22 && ai.pos.distanceTo(ball.pos) > 25) {
707:       let best = null;
708:       let bestD = Infinity;
709:       for (const pad of arena.boostPads) {
710:         if (pad.cooldown > 0) continue;
711:         const d = Math.hypot(ai.pos.x - pad.x, ai.pos.z - pad.z);
712:         if (d < bestD) { bestD = d; best = pad; }
713:       }
714:       if (best) target.set(best.x, 0, best.z);
715:     }
716:     game.aiTarget.copy(target);
717:   }
718: 
719:   const target = game.aiTarget;
720:   const dx = target.x - ai.pos.x;
721:   const dz = target.z - ai.pos.z;
722:   const dist = Math.hypot(dx, dz);
723:   const desiredYaw = Math.atan2(dx, dz);
724:   let angle = wrapAngle(desiredYaw - ai.yaw);
725:   let steer = THREE.MathUtils.clamp(angle * 2.6, -1, 1);
726:   let throttle = 1;
727: 
728:   if (game.aiReverse > 0) {
729:     throttle = -0.8;
730:     steer = -steer;
731:   } else if (Math.abs(angle) > 2.0 && dist < 8) {
732:     throttle = 0.25;
733:   } else if (dist < 2.4) {
734:     throttle = 0.45;
735:   }
736: 
737:   // Stuck detection
738:   if (Math.abs(throttle) > 0.6 && ai.speed < 2.2 && ai.pos.distanceTo(ball.pos) > 5) {
739:     game.aiStuck += dt;
740:     if (game.aiStuck > 0.8) {
741:       game.aiStuck = 0;
742:       game.aiReverse = 0.55;
743:     }
744:   } else {
745:     game.aiStuck = Math.max(0, game.aiStuck - dt * 2);
746:   }
747: 
748:   const ballDist = Math.hypot(ai.pos.x - ball.pos.x, ai.pos.z - ball.pos.z);
749:   const aligned = Math.abs(angle) < 0.38;
750:   const wantBoost = ai.boost > 12 && aligned && dist > 13 && Math.random() < cfg.boost;
751:   if (wantBoost && game.aiBoostCooldown <= 0) {
752:     game.aiBoostCooldown = 0.1;
753:   }
754: 
755:   // Jump for aerial balls
756:   let jumpPressed = false;
757:   if (ai.grounded && game.aiJumpCooldown <= 0 && ballDist < 7.2) {
758:     const heightDiff = ball.pos.y - (ai.pos.y + 1.2);
759:     if (heightDiff > 1.4 && Math.random() < cfg.jump) {
760:       jumpPressed = true;
761:       game.aiJumpCooldown = 0.8;
762:     }
763:   }
764:   // Double jump when already airborne and close
765:   if (!ai.grounded && ai.jumpCount === 1 && ai.vel.y < 4 && ballDist < 5.4 && game.aiJumpCooldown <= 0 && Math.random() < cfg.jump * 0.6) {
766:     jumpPressed = true;
767:     game.aiJumpCooldown = 0.7;
768:   }
769: 
770:   return {
771:     throttle,
772:     steer,
773:     boost: wantBoost && game.aiBoostCooldown <= 0.05,
774:     drift: Math.abs(angle) > 1.0 && ai.speed > 13,
775:     jumpPressed,
776:   };
777: }
