802: // ---------------------------------------------------------------- camera
803: const lookSmooth = new THREE.Vector3(0, 1.2, 0);
804: let airCamY = 0;
805: let camYawSmooth = Math.PI / 2;
806: 
807: function updateCamera(dt, elapsed) {
808:   const shakeAmt = game.shake;
809:   game.shake = Math.max(0, game.shake - dt * 1.6);
810:   const sx = (Math.random() - 0.5) * shakeAmt * 0.8;
811:   const sy = (Math.random() - 0.5) * shakeAmt * 0.8;
812: 
813:   if (game.mode === 'menu' || game.mode === 'boot') {
814:     game.menuAngle += dt * 0.1;
815:     const angle = game.menuAngle;
816:     const desired = new THREE.Vector3(
817:       player.pos.x + Math.sin(angle) * 12.6,
818:       4.2 + Math.sin(elapsed * 0.4) * 0.2,
819:       player.pos.z + Math.cos(angle) * 12.6,
820:     );
821:     camera.position.lerp(desired, 1 - Math.exp(-3 * dt));
822:     const center = new THREE.Vector3(player.pos.x, 1.08, player.pos.z);
823:     const toCar = center.clone().sub(camera.position).normalize();
824:     const camRight = new THREE.Vector3().crossVectors(toCar, UP).normalize();
825:     const camUp = new THREE.Vector3().crossVectors(camRight, toCar).normalize();
826:     const narrow = window.innerWidth < 1240;
827:     const shiftX = narrow ? 3.85 : 2.65;
828:     const shiftY = narrow ? 3.15 : 2.45;
829:     const lookTarget = center.clone().addScaledVector(camRight, -shiftX).addScaledVector(camUp, -shiftY);
830:     lookSmooth.lerp(lookTarget, 1 - Math.exp(-5 * dt));
831:     camera.lookAt(lookSmooth);
832:     camera.fov = THREE.MathUtils.lerp(camera.fov, 52, 1 - Math.exp(-3 * dt));
833:     camera.updateProjectionMatrix();
834:     return;
835:   }
836: 
837:   if (game.mode === 'goal') {
838:     const side = game.goalSide;
839:     const desired = new THREE.Vector3(side * (FIELD.halfX - 15), 10.5, 12 * Math.sin(game.stateTime * 0.4 + 0.4));
840:     camera.position.lerp(desired, 1 - Math.exp(-3.2 * dt));
841:     lookSmooth.lerp(ball.pos, 1 - Math.exp(-4.5 * dt));
842:     camera.lookAt(lookSmooth);
843:     camera.fov = THREE.MathUtils.lerp(camera.fov, 62, 1 - Math.exp(-3 * dt));
844:     camera.updateProjectionMatrix();
845:     return;
846:   }
847: 
848:   const forward = player.forward;
849:   const speed = player.speed;
850:   const airborne = Math.max(0, player.pos.y - 1) * 0.45;
851:   airCamY = THREE.MathUtils.damp(airCamY, airborne, 4, dt);
852:   const dist = 11.4 + Math.min(2.2, speed * 0.04);
853: 
854:   // Ball cam orbits the camera to the far side of the car from the ball, so
855:   // both the car and the ball stay framed no matter which way the car faces.
856:   let camYaw = player.yaw;
857:   if (game.ballCam) {
858:     const dx = ball.pos.x - player.pos.x;
859:     const dz = ball.pos.z - player.pos.z;
860:     const flatDist = Math.hypot(dx, dz);
861:     if (flatDist > 0.001) {
862:       const ballYaw = Math.atan2(dx, dz);
863:       const blend = THREE.MathUtils.smoothstep(flatDist, 3, 9);
864:       camYaw = player.yaw + wrapAngle(ballYaw - player.yaw) * blend;
865:     }
866:   }
867:   const yawRate = game.ballCam ? 5.2 : 7.5;
868:   camYawSmooth += wrapAngle(camYaw - camYawSmooth) * (1 - Math.exp(-yawRate * dt));
869: 
870:   // Keep the camera inside the arena shell. When the ideal spot is behind a
871:   // wall, orbit the camera sideways instead of letting the car fall out of
872:   // frame (and never let it clip into the stands).
873:   const limitX = FIELD.halfX - 2.2;
874:   const limitZ = FIELD.halfZ - 2.2;
875:   const fits = (yaw, radius) => {
876:     const x = player.pos.x - Math.sin(yaw) * radius;
877:     const z = player.pos.z - Math.cos(yaw) * radius;
878:     return Math.abs(x) <= limitX && Math.abs(z) <= limitZ ? { x, z } : null;
879:   };
880:   let camX = player.pos.x - Math.sin(camYawSmooth) * dist;
881:   let camZ = player.pos.z - Math.cos(camYawSmooth) * dist;
882:   let wallPush = 0;
883:   if (Math.abs(camX) > limitX || Math.abs(camZ) > limitZ) {
884:     const offsets = [0, 0.45, -0.45, 0.9, -0.9, 1.35, -1.35, 1.8, -1.8, 2.25, -2.25, Math.PI];
885:     const scales = [1, 0.82, 0.66, 0.52];
886:     let found = false;
887:     for (const scale of scales) {
888:       for (const off of offsets) {
889:         const spot = fits(camYawSmooth + off, dist * scale);
890:         if (spot) {
891:           camX = spot.x;
892:           camZ = spot.z;
893:           wallPush = (1 - scale) * 3;
894:           found = true;
895:           break;
896:         }
897:       }
898:       if (found) break;
899:     }
900:     if (!found) {
901:       camX = THREE.MathUtils.clamp(camX, -limitX, limitX);
902:       camZ = THREE.MathUtils.clamp(camZ, -limitZ, limitZ);
903:       wallPush = 3;
904:     }
905:   }
906:   const desired = new THREE.Vector3(camX, 4.05 + airCamY + wallPush, camZ);
907:   camera.position.lerp(desired, 1 - Math.exp(-10 * dt));
908:   camera.position.x = THREE.MathUtils.clamp(camera.position.x, -limitX, limitX);
909:   camera.position.z = THREE.MathUtils.clamp(camera.position.z, -limitZ, limitZ);
910:   camera.position.y = Math.max(1.6, camera.position.y);
911: 
912:   const lookTarget = new THREE.Vector3();
913:   if (game.ballCam) {
914:     lookTarget.copy(ball.pos);
915:     lookTarget.y = Math.max(1.3, ball.pos.y + 0.25);
916:   } else {
917:     lookTarget.copy(player.pos).addScaledVector(forward, 11);
918:     lookTarget.y += 1.1;
919:   }
920:   lookSmooth.lerp(lookTarget, 1 - Math.exp(-12 * dt));
921:   camera.lookAt(lookSmooth);
922:   const targetFov = 63 + Math.min(9, speed * 0.2) + (player.boosting ? 3.5 : 0);
923:   camera.fov = THREE.MathUtils.damp(camera.fov, targetFov, 4, dt);
924:   camera.updateProjectionMatrix();
925: 
926:   camera.position.x += sx;
927:   camera.position.y += sy;
928:   camera.lookAt(lookSmooth);
929: }
