937:   if (count !== game.lastCount && count > 0) {
938:     game.lastCount = count;
939:     showCenter(String(count), count === 1 ? 'warn' : '', 650);
940:     audio.countdown(false);
941:   }
942:   if (game.countdown <= 0) {
943:     game.mode = 'playing';
944:     game.stateTime = 0;
945:     ball.frozen = false;
946:     showCenter('GO', 'go', 700);
