951: function updatePlaying(dt) {
952:   currentInput = readPlayerInput();
953:   const aiIn = aiInput(dt);
954:   player.update(dt, currentInput, ball, {
955:     boost: (c) => { if (c === player) fx.boost(c, dt); },
956:     jump: () => audio.jump(),
957:     flip: () => audio.flip(),
958:     land: (c, imp) => { if (c === player) { audio.land(imp); game.shake = Math.max(game.shake, Math.min(0.24, imp * 0.018)); } fx.land(c, imp); },
959:     hit: (c, b, impact, normal) => {
960:       if (c === player) {
961:         audio.hit(impact);
962:         game.shake = Math.max(game.shake, Math.min(0.5, impact * 0.016));
963:         game.stats.hits += 1;
964:         if (impact > 12) showToast(impact > 30 ? 'ROCKET HIT!' : 'CLEAN HIT', 0.9);
965:       }
966:       fx.hit(c, b, impact, normal);
967:     },
968:   });
969:   ai.update(dt, aiIn, ball, {
970:     boost: (c) => fx.boost(c, dt),
971:     hit: (c, b, impact, normal) => fx.hit(c, b, impact, normal),
972:     land: (c, imp) => fx.land(c, imp),
973:     jump: () => {},
974:     flip: () => {},
975:   });
976: 
977:   const goal = ball.update(dt, {
978:     bounce: (b, imp) => { fx.bounce(b, imp); if (b.pos.distanceTo(player.pos) < 18) audio.bounce(imp); },
979:     wallBounce: (b) => { fx.wallBounce(b); if (b.pos.distanceTo(player.pos) < 20) audio.bounce(3); },
980:   });
981:   fx.trail(ball);
982: 
983:   updatePads();
984:   checkClock(dt);
985:   if (game.mode !== 'playing') return;
986: 
987:   game.stats.topSpeed = Math.max(game.stats.topSpeed, player.topSpeed);
988:   game.stats.boostUsed = player.boostUsed;
989:   game.stats.distance += player.speed * dt;
990:   game.stats.possession += ball.lastTouch === 'blue' ? dt : 0;
991:   if (ball.lastTouch === 'blue') game.shotCooldown = Math.max(0, game.shotCooldown - dt);
992: 
993:   if (goal) scoreGoal(goal);
994: 
995:   audio.setEngine(player.speed, player.boosting, true);
996: }
