998: function update(dt, elapsed) {
999:   arena.update(dt, elapsed);
1000:   fx.update(dt);
1001: 
1002:   if (game.mode === 'menu') {
1003:     player.updateVisual(dt, elapsed);
1004:     ai.updateVisual(dt, elapsed);
1005:   } else if (game.mode === 'countdown') {
1006:     game.stateTime += dt;
1007:     player.updateVisual(dt, elapsed);
1008:     ai.updateVisual(dt, elapsed);
1009:     updateCountdown(dt);
1010:   } else if (game.mode === 'playing') {
1011:     game.stateTime += dt;
1012:     updatePlaying(dt);
1013:     player.updateVisual(dt, elapsed);
1014:     ai.updateVisual(dt, elapsed);
1015:   } else if (game.mode === 'goal') {
1016:     game.stateTime += dt;
1017:     // let the cars coast out with no input
1018:     const idle = { throttle: 0, steer: 0, boost: false, drift: false, jumpPressed: false };
1019:     player.update(dt, idle, ball);
1020:     ai.update(dt, idle, ball);
1021:     player.updateVisual(dt, elapsed);
1022:     ai.updateVisual(dt, elapsed);
1023:     ball.update(dt);
1024:     if (game.stateTime > 3.1) afterGoal();
