442: export class Car {
443:   constructor(scene, { team, build, isPlayer = false, name = 'PLAYER', number = '07' }) {
444:     this.scene = scene;
445:     this.team = team;
446:     this.teamKey = team.key;
447:     this.build = build;
448:     this.isPlayer = isPlayer;
449:     this.name = name;
450:     this.number = number;
451:     this.pos = new THREE.Vector3();
452:     this.vel = new THREE.Vector3();
453:     this.yaw = 0;
454:     this.steer = 0;
455:     this.grounded = true;
456:     this.jumpCount = 0;
457:     this.boost = 33;
458:     this.boosting = false;
459:     this.hitCooldown = 0;
460:     this.visualRoll = 0;
461:     this.visualPitch = 0;
462:     this.wheelSpin = 0;
463:     this.flipTimer = 0;
464:     this.landTimer = 0;
465:     this.boostEmit = 0;
466:     this.topSpeed = 0;
467:     this.boostUsed = 0;
468:     this.hits = 0;
469:     this.stats = build.physics;
470:     this.visual = buildCarVisual(build, team, { isPlayer, number });
471:     this.scene.add(this.visual.group);
472:     this.visual.group.position.copy(this.pos);
473:   }
474: 
475:   setBuild(build) {
476:     const boostFrac = this.stats.capacity ? this.boost / this.stats.capacity : 0.33;
477:     const old = this.visual;
478:     this.scene.remove(old.group);
479:     disposeGroup(old.group);
480:     this.build = build;
481:     this.stats = build.physics;
482:     this.visual = buildCarVisual(build, this.team, { isPlayer: this.isPlayer, number: this.number });
483:     this.scene.add(this.visual.group);
484:     this.boost = boostFrac * this.stats.capacity;
485:     this.visual.group.position.copy(this.pos);
486:     this.visual.group.rotation.y = this.yaw;
487:   }
488: 
489:   reset(x, z, yaw, boost = 33) {
490:     this.pos.set(x, 0, z);
491:     this.vel.set(0, 0, 0);
492:     this.yaw = yaw;
493:     this.steer = 0;
494:     this.grounded = true;
495:     this.jumpCount = 0;
496:     this.boost = Math.min(boost, this.stats.capacity);
497:     this.boosting = false;
498:     this.hitCooldown = 0;
499:     this.visual.group.position.copy(this.pos);
500:     this.visual.group.rotation.y = yaw;
501:     this.visual.bodyGroup.rotation.set(0, 0, 0);
502:     this.visual.group.visible = true;
503:   }
504: 
505:   get forward() {
506:     return new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw));
507:   }
508: 
509:   get right() {
510:     return new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
511:   }
512: 
513:   get speed() {
514:     return Math.hypot(this.vel.x, this.vel.z);
515:   }
516: 
517:   addBoost(amount) {
518:     const before = this.boost;
519:     this.boost = Math.min(this.stats.capacity, this.boost + amount);
520:     return this.boost > before;
521:   }
522: 
523:   update(dt, input, ball, effects = {}) {
524:     const stats = this.stats;
525:     this.hitCooldown = Math.max(0, this.hitCooldown - dt);
526:     this.flipTimer = Math.max(0, this.flipTimer - dt);
527:     this.landTimer = Math.max(0, this.landTimer - dt);
528: 
529:     let forward = this.forward;
530:     let right = this.right;
531:     const fwdSpeed = this.vel.dot(forward);
532: 
533:     // Steering
534:     const dirSign = fwdSpeed < -0.8 ? -1 : 1;
535:     const speedFactor = this.grounded
536:       ? THREE.MathUtils.clamp(0.34 + Math.abs(fwdSpeed) / 9, 0.34, 1.08)
537:       : 0.55;
538:     const driftMul = input.drift && this.grounded ? 1.42 : 1;
539:     this.steer = damp(this.steer, input.steer, 14, dt);
540:     this.yaw += this.steer * stats.steerRate * speedFactor * driftMul * dirSign * dt;
541: 
542:     forward = this.forward;
543:     right = this.right;
544: 
545:     // Throttle
546:     let engineForce = 0;
547:     if (input.throttle > 0) {
548:       engineForce = stats.accel * input.throttle;
549:       if (fwdSpeed > stats.maxSpeed * 0.99) engineForce *= 0.15;
550:     } else if (input.throttle < 0) {
551:       if (fwdSpeed > 1.5) engineForce = -stats.accel * 1.35 * -input.throttle;
552:       else engineForce = stats.accel * 0.52 * input.throttle;
553:     }
554:     if (this.grounded) this.vel.addScaledVector(forward, engineForce * dt);
555:     else this.vel.addScaledVector(forward, engineForce * 0.28 * dt);
556: 
557:     // Boost
558:     const wantsBoost = !!input.boost && this.boost > 0.15;
559:     this.boosting = wantsBoost;
560:     if (wantsBoost) {
561:       const thrustAccel = 29 * stats.thrust;
562:       this.vel.addScaledVector(forward, thrustAccel * dt);
563:       if (!this.grounded) this.vel.y += 1.6 * dt;
564:       this.boost = Math.max(0, this.boost - stats.drain * dt);
565:       this.boostUsed += stats.drain * dt;
566:       this.boostEmit += dt;
567:       if (effects.boost) effects.boost(this, dt);
568:     } else if (stats.regen > 0) {
569:       this.boost = Math.min(stats.capacity, this.boost + stats.regen * dt);
570:     }
571: 
572:     // Grip and drag
573:     const lateral = this.vel.dot(right);
574:     const gripMul = this.grounded ? (input.drift ? 0.34 : 1) : 0.16;
575:     this.vel.addScaledVector(right, -lateral * Math.min(1, stats.grip * gripMul * dt));
576:     if (this.grounded) {
577:       const forwardDrag = input.throttle === 0 ? 0.85 : 0.16;
578:       const fwdComponent = this.vel.dot(forward);
579:       this.vel.addScaledVector(forward, -fwdComponent * Math.min(1, forwardDrag * dt));
580:     } else {
581:       this.vel.multiplyScalar(Math.exp(-0.08 * dt));
582:     }
583: 
584:     // Speed cap
585:     const flatSpeed = Math.hypot(this.vel.x, this.vel.z);
586:     const cap = stats.maxSpeed * (this.boosting ? 1.26 : 1.0);
587:     if (flatSpeed > cap) {
588:       const s = cap / flatSpeed;
589:       this.vel.x *= s;
590:       this.vel.z *= s;
591:     }
592: 
593:     // Jump / double jump
594:     if (input.jumpPressed) {
595:       if (this.grounded) {
596:         this.vel.y = stats.jumpSpeed;
597:         this.grounded = false;
598:         this.jumpCount = 1;
599:         this.landTimer = 0;
600:         if (effects.jump) effects.jump(this);
601:       } else if (this.jumpCount < 2) {
602:         this.vel.y = Math.max(this.vel.y, stats.jumpSpeed * 0.82);
603:         this.jumpCount = 2;
604:         const dir = new THREE.Vector3();
605:         dir.addScaledVector(forward, input.throttle);
606:         dir.addScaledVector(right, input.steer);
607:         if (dir.lengthSq() > 0.05) {
608:           dir.normalize();
609:           this.vel.addScaledVector(dir, 9.5 * (0.85 + stats.handling * 0.02));
610:           this.vel.y += 2.4;
611:         }
612:         this.flipTimer = 0.55;
613:         if (effects.flip) effects.flip(this);
614:       }
615:     }
616: 
617:     // Gravity
618:     if (!this.grounded) this.vel.y -= 37 * dt;
619: 
620:     // Integrate
621:     this.pos.addScaledVector(this.vel, dt);
622: 
623:     // Ground
624:     if (this.pos.y <= 0) {
625:       const impact = -this.vel.y;
626:       this.pos.y = 0;
627:       if (!this.grounded && impact > 3 && effects.land) effects.land(this, impact);
628:       this.vel.y = 0;
629:       this.grounded = true;
630:       this.jumpCount = 0;
631:     } else {
632:       this.grounded = false;
633:     }
634:     if (this.pos.y > FIELD.ceiling - 1.2) {
635:       this.pos.y = FIELD.ceiling - 1.2;
636:       this.vel.y = Math.min(0, this.vel.y);
637:     }
638: 
639:     // Arena walls (cars stay inside the pitch)
640:     const limitX = FIELD.halfX - 1.25;
641:     const limitZ = FIELD.halfZ - 1.1;
642:     if (this.pos.x > limitX) { this.pos.x = limitX; this.vel.x *= -0.28; this.vel.z *= 0.86; }
643:     if (this.pos.x < -limitX) { this.pos.x = -limitX; this.vel.x *= -0.28; this.vel.z *= 0.86; }
644:     if (this.pos.z > limitZ) { this.pos.z = limitZ; this.vel.z *= -0.28; this.vel.x *= 0.86; }
645:     if (this.pos.z < -limitZ) { this.pos.z = -limitZ; this.vel.z *= -0.28; this.vel.x *= 0.86; }
646: 
647:     // Ball collision
648:     if (ball) this.collideBall(ball, effects);
649: 
650:     this.topSpeed = Math.max(this.topSpeed, this.speed);
651:   }
652: 
653:   collideBall(ball, effects) {
654:     if (this.hitCooldown > 0 || ball.frozen) return;
655:     const dims = this.stats.dims;
656:     const center = new THREE.Vector3(this.pos.x, this.pos.y + 0.68, this.pos.z);
657:     const forward = this.forward;
658:     const right = this.right;
659:     const delta = new THREE.Vector3().subVectors(ball.pos, center);
660:     const localX = delta.dot(right);
661:     const localZ = delta.dot(forward);
662:     const halfX = dims.width * 0.47;
663:     const halfY = 0.5;
664:     const halfZ = dims.length * 0.46;
665:     const cx = THREE.MathUtils.clamp(localX, -halfX, halfX);
666:     const cy = THREE.MathUtils.clamp(delta.y, -halfY, halfY);
667:     const cz = THREE.MathUtils.clamp(localZ, -halfZ, halfZ);
668:     const closest = new THREE.Vector3()
669:       .copy(center)
670:       .addScaledVector(right, cx)
671:       .addScaledVector(UP, cy)
672:       .addScaledVector(forward, cz);
673:     const diff = new THREE.Vector3().subVectors(ball.pos, closest);
674:     let dist = diff.length();
675:     if (dist > ball.radius) return;
676: 
677:     let normal;
678:     if (dist < 0.0001) {
679:       normal = new THREE.Vector3(0, 1, 0);
680:       dist = 0.001;
681:     } else {
682:       normal = diff.divideScalar(dist);
683:     }
684:     const penetration = ball.radius - dist;
685:     ball.pos.addScaledVector(normal, penetration + 0.02);
686: 
687:     const rel = new THREE.Vector3().subVectors(ball.vel, this.vel);
688:     const closing = Math.max(0, -rel.dot(normal));
689:     const carIntoBall = Math.max(0, this.vel.dot(normal));
690:     const impact = Math.max(closing, carIntoBall);
691:     if (impact < 0.4 && penetration < 0.1) return;
692: 
693:     const boostBoost = this.boosting ? 1.14 : 1;
694:     const power = this.stats.hitPower * boostBoost;
695:     const kick = (2.8 + impact * 1.15) * power;
696:     ball.vel.addScaledVector(normal, kick * 0.68);
697:     ball.vel.addScaledVector(this.vel, 0.3 * power);
698:     ball.vel.y += Math.min(8.5, impact * 0.14) * power;
699: 
700:     // Nose punt
701:     const noseDistance = localZ - halfZ;
702:     if (localZ > halfZ * 0.55 && this.speed > 6) {
703:       ball.vel.addScaledVector(forward, this.speed * 0.36 * power);
704:     }
705:     if (noseDistance > 0 && normal.y < 0.6) {
706:       ball.vel.y += Math.min(3.4, this.speed * 0.06);
707:     }
708: 
709:     // Recoil
710:     this.vel.addScaledVector(normal, -impact * 0.018 / this.stats.weight);
711:     this.hitCooldown = 0.1;
712:     this.hits += 1;
713:     ball.lastTouch = this.teamKey;
714:     ball.lastTouchCar = this;
715:     ball.hitFlash = 1;
716:     if (effects.hit) effects.hit(this, ball, impact, normal);
717:   }
718: 
719:   updateVisual(dt, elapsed) {
720:     const v = this.visual;
721:     const fwdSpeed = this.vel.dot(this.forward);
722:     const lateral = this.vel.dot(this.right);
723:     v.group.position.copy(this.pos);
724: 
725:     const targetRoll = THREE.MathUtils.clamp(-this.steer * 0.1 - lateral * 0.006, -0.22, 0.22);
726:     const targetPitch = THREE.MathUtils.clamp((this.grounded ? 0 : -this.vel.dot(this.forward) * 0.0035) + (this.grounded ? 0 : this.vel.y * 0.002), -0.18, 0.18);
727:     this.visualRoll = damp(this.visualRoll, targetRoll, 9, dt);
728:     this.visualPitch = damp(this.visualPitch, targetPitch, 7, dt);
729:     v.bodyGroup.rotation.z = this.visualRoll;
730:     v.bodyGroup.rotation.x = this.visualPitch + (this.flipTimer > 0 ? Math.sin((0.55 - this.flipTimer) / 0.55 * Math.PI * 2) * 0.18 : 0);
731:     v.group.rotation.y = this.yaw;
732: 
733:     this.wheelSpin += (fwdSpeed * dt) / Math.max(0.3, v.wheelRadius);
734:     for (const wheel of v.wheels) {
735:       wheel.spinner.rotation.x = this.wheelSpin;
736:       if (wheel.front) wheel.pivot.rotation.y = this.steer * 0.42;
737:     }
738: 
739:     for (let i = 0; i < v.flames.length; i += 1) {
740:       const { flame, core } = v.flames[i];
741:       const on = this.boosting && this.boost > 0.1;
742:       flame.visible = on;
743:       core.visible = on;
744:       if (on) {
745:         const flicker = 0.82 + Math.sin(elapsed * 42 + i * 2.1) * 0.16 + Math.random() * 0.08;
746:         const length = 0.7 + Math.min(1.25, this.speed / 26) * 0.7;
747:         flame.scale.set(flicker, length, flicker);
748:         core.scale.set(1, length * 0.9, 1);
749:       }
750:       v.boostLights[i].intensity = on ? 1.8 + Math.random() * 0.9 : 0;
751:     }
752:     if (v.topperSpin) {
753:       if (this.build.chosen.topper.id === 'propeller') v.topperSpin.rotation.y += dt * (this.boosting ? 22 : 9);
754:       else if (this.build.chosen.topper.id === 'halo') v.topperSpin.rotation.z += dt * 0.8;
755:       else if (this.build.chosen.topper.id === 'satellite') v.topperSpin.rotation.y += dt * 0.5;
756:     }
757:     v.indicator.material.opacity = (this.isPlayer ? 0.32 : 0.16) + Math.sin(elapsed * 3) * 0.05;
758:   }
759: 
760:   dispose() {
761:     this.scene.remove(this.visual.group);
762:     disposeGroup(this.visual.group);
763:   }
764: }
